		self.status.area, self.status.totalAreas = snapshot.area, snapshot.totalAreas
		local scope = snapshot.dungeonId
			.. "/"
			.. snapshot.runId
			.. "/"
			.. snapshot.area
			.. "/"
			.. tostring(snapshot.characterId)
