			self.machine:Set("FIND_NPCS", "Dungeon, area, or character changed")
		end
		if self.retryAt then
			if now < self.retryAt then
				return
			end
			self.retryAt = nil
		end
		if snapshot.completed then
			self:_complete(snapshot, now, config)
			return
		end
		if self.completedRun and snapshot.runId == self.completedRun then
			self:_wait("replay", "RECOVERING", "Waiting for a new run identity", now, config, true)
			return
		end
		if not snapshot.characterReady then
			self:_wait("character", "RECOVERING", "Waiting for character respawn", now, config, true)
			return
		end
		local inspection = DungeonController.inspect(snapshot)
		self.status.npcsRemaining = #inspection.npcs
		self.status.rubble = if inspection.rubble
			then string.format("Active · %.0f HP", inspection.rubble.health)
			else "No active barrier"
		if inspection.objective == "NPCs" then
			if not config.autoFarm and not config.killAura then
				self:_wait("pausedNPC", "FIND_NPCS", "NPC farming is paused", now, config, false)
				return
			end
			local refresh = now - self.lastRefresh >= config.targetRefreshInterval
			local targeting = config
			if config.killAura and not config.autoFarm then
				targeting = table.clone(config)
				targeting.maxTargetDistance = config.attackRange
			end
			local target = NPCDetector.select(snapshot, targeting, self.targetId, refresh)
			if refresh then
				self.lastRefresh = now
			end
			if not target then
				if config.killAura and not config.autoFarm then
					self:_wait(
						"auraRange",
						"FIND_NPCS",
						"Kill Aura: waiting for a living NPC within attack range",
						now,
						config,
						false
					)
					return
				end
				self:_wait("outOfRange", "FIND_NPCS", "Enemies are outside target distance", now, config, true)
				return
			end
			self.waitKey = nil
			if target.id ~= self.targetId then
				self.combat:Cancel()
				self.logger:Log("DEBUG", "NPC target acquired", target.id)
			end
			self.targetId, self.status.target = target.id, target.name or target.id
			local result
			if config.killAura and not config.autoFarm then
				self.movement:Cancel()
				self.status.destination = "None (Kill Aura does not pursue NPCs)"
				result = "arrived"
			else
				result = self:_move(
					target,
					snapshot,
					now,
					config,
					if config.killAura then config.attackRange else config.followDistance,
					"MOVE_TO_NPC"
				)
			end
			if result == "arrived" then
				self.machine:Set("ATTACK_NPCS", self.status.target)
				local ok, err = self.combat:Attack("NPC", target, snapshot, now, config)
				if not ok then
					self:_recover(err or "Combat action rejected", now)
				end
			else
				self.combat:Cancel()
			end
			return
		end
		if self.targetId then
			self.combat:Cancel()
		end
		self.targetId = nil
		if inspection.objective == "Wait" then
			self:_wait(
				"spawn",
				"WAIT_FOR_NPC_SPAWN",
				"Waiting for wave or area-clear confirmation",
				now,
				config,
				config.waitForNPCSpawn
			)
			return
		end
		if self.clearedScope ~= scope then
			self.clearedScope = scope
			self.machine:Set("CHECK_AREA_COMPLETION", "Area cleared by verified state")
			self.machine:Set("FIND_RUBBLE", "Checking progression objectives")
		end
		if inspection.objective == "Rubble" then
			if not config.autoBreakRubble then
				self:_wait("pausedRubble", "FIND_RUBBLE", "Rubble breaking is paused", now, config, false)
				return
			end
			self.waitKey = nil
			local target = inspection.target
			self.status.target = target.name or target.id
			local result = self:_move(target, snapshot, now, config, config.followDistance, "MOVE_TO_RUBBLE")
			if result == "arrived" then
				self.machine:Set("BREAK_RUBBLE", self.status.target)
				local ok, err = self.combat:Attack("Rubble", target, snapshot, now, config)
				if not ok then
					self:_recover(err or "Rubble action rejected", now)
				end
			else
				self.combat:Cancel()
			end
		elseif inspection.objective == "Entrance" then
			self.combat:Cancel()
			if not config.autoNextArea then
				self:_wait(
					"pausedEntrance",
					"MOVE_TO_NEXT_AREA",
					"Next-area movement is paused",
					now,
					config,
					false
				)
				return
			end
			local result = self:_move(inspection.target, snapshot, now, config, 2.5, "MOVE_TO_NEXT_AREA")
			if result == "arrived" then
				self:_wait(
					"entrance",
					"WAIT_FOR_NPC_SPAWN",
					"Waiting for next-area entry confirmation",
					now,
					config,
					true
				)
			else
				self.waitKey = nil
			end
		else
			self:_wait(
				"objective",
				"FIND_RUBBLE",
				"Waiting for rubble, entrance, or completion state",
				now,
				config,
				true
			)
		end
	end

	function AutomationController:Tick(now)
		if self.destroyed or not self.enabled then
			return
		end
		local ok, err = xpcall(function()
			local available, problem = self:_preflight()
			if not available then
				self:_fail(problem)
				return
			end
			self:_step(self.adapter:snapshot(), now)
		end, debug.traceback)
		if not ok then
			self:_fail(err)
		end
		self:_publish()
	end

	function AutomationController:Destroy()
		if self.destroyed then
			return
		end
		self:Stop("Controller unloaded")
		self.destroyed = true
		self.configConnection:Disconnect()
		self.stateConnection:Disconnect()
		for _, dispose in
			{
				function()
					self.combat:Destroy()
				end,
				function()
					self.movement:Destroy()
				end,
				function()
					self.adapter:destroy()
				end,
			}
		do
			local ok, err = pcall(dispose)
			if not ok then
				self.logger:Log("WARN", "Controller cleanup failed", err)
			end
		end
		self.machine:Destroy()
		self.Changed:Destroy()
	end

	return AutomationController
end

-- Module: src/Core/Configuration.lua
__factories["Core/Configuration"] = function(__require)
	local Signal = __require("Utils/Signal")
	local Geometry = __require("Utils/Geometry")
	local Configuration = {}
	Configuration.__index = Configuration
	Configuration.VERSION = 1
	Configuration.defaults = table.freeze({
		autoFarm = true,
		killAura = false,
		autoBreakRubble = true,
		autoNextArea = true,
		autoRetry = false,
		waitForNPCSpawn = true,
		targetingMode = "Nearest",
		maxTargetDistance = 180,
		attackRange = 8,
		followDistance = 5,
		targetRefreshInterval = 0.5,
		attackInterval = 0.6,
		combatProgressTimeout = 15,
		movementMode = "Pathfinding",
		applyMovementSpeed = false,
		movementSpeed = 16,
		stuckDetection = true,
		stuckTimeout = 5,
		movementTimeout = 35,
		spawnWaitTimeout = 30,
		maxRecoveryAttempts = 3,
		notifications = true,
		debug = false,
	})
	local ranges = {
		maxTargetDistance = { 10, 500 },
		attackRange = { 2, 20 },
		followDistance = { 1, 18 },
		targetRefreshInterval = { 0.1, 3 },
		attackInterval = { 0.1, 3 },
		combatProgressTimeout = { 5, 120 },
		movementSpeed = { 8, 32 },
		stuckTimeout = { 2, 20 },
		movementTimeout = { 5, 120 },
		spawnWaitTimeout = { 5, 120 },
		maxRecoveryAttempts = { 0, 5 },
	}
	local options = {
		targetingMode = { Nearest = true, LowestHealth = true },
		movementMode = { Pathfinding = true, MoveTo = true },
	}

	function Configuration.new(saved)
		local self =
			setmetatable({ values = table.clone(Configuration.defaults), Changed = Signal.new() }, Configuration)
		if saved then
			self:Load(saved)
		end
		return self
	end

	function Configuration:Set(key, value)
		local default = Configuration.defaults[key]
		if default == nil or type(value) ~= type(default) then
			return false, "Invalid preference: " .. tostring(key)
		end
		if ranges[key] then
			if not Geometry.finite(value) then
				return false, "Value must be finite"
			end
			value = math.clamp(value, ranges[key][1], ranges[key][2])
		elseif options[key] and not options[key][value] then
			return false, "Unsupported option: " .. tostring(value)
		end
		self.values[key] = value
		self.values.followDistance = math.min(self.values.followDistance, self.values.attackRange)
		self.Changed:Fire(self:Get())
		return true
	end

	function Configuration:Get()
		return table.clone(self.values)
	end

	function Configuration:Load(saved)
		if type(saved) ~= "table" or saved.version ~= Configuration.VERSION or type(saved.values) ~= "table" then
			return false, "Unsupported preference format"
		end
		-- Apply range first so table iteration order cannot change followDistance.
		self:Set("attackRange", saved.values.attackRange or self.values.attackRange)
		for key, value in saved.values do
			if key ~= "attackRange" and key ~= "followDistance" then
				self:Set(key, value)
			end
		end
		self:Set("followDistance", saved.values.followDistance or self.values.followDistance)
		return true
	end

	function Configuration:Export()
		return { version = Configuration.VERSION, values = self:Get() }
	end

	function Configuration:Reset()
		self.values = table.clone(Configuration.defaults)
		self.Changed:Fire(self:Get())
	end

	function Configuration:Destroy()
		self.Changed:Destroy()
	end

	return Configuration
end

-- Module: src/Core/Logger.lua
__factories["Core/Logger"] = function(__require)
	local Signal = __require("Utils/Signal")
	local Logger = {}
	Logger.__index = Logger

	function Logger.new(config, sink)
		return setmetatable(
			{ config = config, sink = sink or print, entries = {}, Message = Signal.new() },
			Logger
		)
	end

	function Logger:Log(level, message, context)
		if level == "DEBUG" and not self.config:Get().debug then
			return
		end
		local entry = { level = level, message = message, context = context }
		table.insert(self.entries, entry)
		if #self.entries > 150 then
			table.remove(self.entries, 1)
		end
		self.sink(
			"[Mohammad & Ali] [" .. level .. "] " .. message .. (context and " | " .. tostring(context) or "")
		)
		self.Message:Fire(entry)
	end

	function Logger:Destroy()
		self.Message:Destroy()
		table.clear(self.entries)
	end

	return Logger
end

-- Module: src/Game/AnimeZeroAdapter.lua
__factories["Game/AnimeZeroAdapter"] = function(__require)
	-- No live Anime Zero hierarchy, remotes, or combat API have been verified.
	-- Supply developer-authorized, non-yielding bindings; fail closed otherwise.
	local Adapter = {}
	Adapter.__index = Adapter

	function Adapter.new(bindings)
		bindings = bindings or {}
		return setmetatable({
			bindings = bindings,
			capabilities = {
				snapshot = type(bindings.snapshot) == "function",
				attack = type(bindings.attack) == "function",
				breakRubble = type(bindings.breakRubble) == "function",
				replay = type(bindings.requestReplay) == "function",
				preferences = type(bindings.savePreferences) == "function",
				movementSpeed = bindings.movementSpeed == true,
			},
		}, Adapter)
	end

	function Adapter:integrationStatus()
		local missing = {}
		for _, key in { "snapshot", "attack", "breakRubble", "requestReplay" } do
			if type(self.bindings[key]) ~= "function" then
				table.insert(missing, key)
			end
		end
		return {
			configured = #missing == 0,
			missing = missing,
			summary = if #missing > 0
				then "Missing game bindings: " .. table.concat(missing, ", ")
				else "Bindings supplied; real gameplay still requires validation",
			replay = if self.capabilities.replay
				then "Replay binding supplied; completion and new-run confirmation required"
				else "Auto Retry unavailable: missing requestReplay binding and confirmed completion/new-run state",
		}
	end

	function Adapter:preflight(config)
		local required = { "snapshot" }
		if config.autoFarm or config.killAura then
			table.insert(required, "attack")
		end
		if config.autoBreakRubble then
			table.insert(required, "breakRubble")
		end
		if config.autoRetry then
			table.insert(required, "requestReplay")
		end
		local missing = {}
		for _, key in required do
			if type(self.bindings[key]) ~= "function" then
				table.insert(missing, key)
			end
		end
		if #missing > 0 then
			return false,
				"Integration unavailable: missing "
					.. table.concat(missing, ", ")
					.. ". Automation stopped; open Diagnostics. Recovery cannot create game bindings."
		end
		return true
	end

	function Adapter:snapshot()
		if not self.bindings.snapshot then
			return {
				ready = false,
				blocked = true,
				reason = "Missing snapshot binding: dungeon/run/area, NPCs, rubble and completion are unknown. Open Diagnostics.",
			}
		end
		return self.bindings.snapshot()
	end

	function Adapter:attack(kind, id, runId)
		local action = if kind == "NPC" then self.bindings.attack else self.bindings.breakRubble
		if not action then
			return false, "Combat binding is unavailable"
		end
		return action(id, runId)
	end

	function Adapter:cancelCombat()
		if self.bindings.cancelCombat then
			self.bindings.cancelCombat()
		end
	end

	function Adapter:requestReplay(runId)
		if not self.bindings.requestReplay then
			return false, "Replay binding is unavailable"
		end
		return self.bindings.requestReplay(runId)
	end

	function Adapter:savePreferences(preferences)
		if not self.bindings.savePreferences then
			return false, "Preference persistence is unavailable"
		end
		return self.bindings.savePreferences(preferences)
	end

	function Adapter:loadPreferences()
		if self.bindings.loadPreferences then
			return self.bindings.loadPreferences()
		end
		return nil
	end

	function Adapter:destroy()
		self:cancelCombat()
		if self.bindings.destroy then
			self.bindings.destroy()
		end
	end

	return Adapter
end

